<?php $pageTitle='Users';require_once dirname(__DIR__).'/includes/header.php';require_once dirname(__DIR__).'/includes/auth.php';require_auth(['super_admin']);if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf_token']??null);$username=trim($_POST['username']??'');$password=$_POST['password']??'';if(strlen($username)<3||strlen($password)<8)throw new RuntimeException('Username min. 3 and password min. 8 characters.');$pdo->prepare('INSERT INTO users (username,password,name,role) VALUES (?,?,?,?)')->execute([$username,password_hash($password,PASSWORD_DEFAULT),trim($_POST['name']),$_POST['role']]);audit_log($pdo,'create','user',(int)$pdo->lastInsertId(),'Created user '.$username);header('Location: users.php?created=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}$users=$pdo->query('SELECT id,username,name,role,created_at FROM users ORDER BY created_at DESC')->fetchAll();require dirname(__DIR__).'/includes/sidebar.php';?>
<div class="grid grid-3"><section class="card"><div class="eyebrow">Access control</div><h2>Add user</h2><?php if(!empty($error)):?><p class="negative"><?=e($error)?></p><?php endif;?><form method="post" class="grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div><label>Name</label><input name="name" required></div><div><label>Username</label><input name="username" required></div><div><label>Password</label><input type="password" name="password" minlength="8" required></div><div><label>Role</label><select name="role"><option value="judge">Judge</option><option value="admin">Admin</option><option value="super_admin">Super Admin</option></select></div><button class="btn btn-primary">Create User</button></form></section><section style="grid-column:span 2"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Created</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['username'])?></td><td><span class="badge"><?=e(str_replace('_',' ',$u['role']))?></span></td><td><?=date('d M Y',strtotime($u['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php require dirname(__DIR__).'/includes/admin_footer.php';?>

